import os
import numpy as np
import pandas as pd

# ============================================================
# ARES 2.0 - FEATURE INSPECTION
# Maps the 115 processed features to their available names
# and prints statistics so we can identify what the model sees.
# ============================================================

BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA_DIR = os.path.join(BASE_DIR, "data")

X_TRAIN_PATH = os.path.join(DATA_DIR, "X_train.npy")
Y_TRAIN_PATH = os.path.join(DATA_DIR, "y_train.npy")

# Possible source files generated by the preparation stage.
# The script checks these automatically.
CANDIDATE_FILES = [
    "mlp_features.csv",
    "processed_features.csv",
    "features.csv",
    "feature_mapping.csv",
    "feature_names.csv"
]

CLASS_NAMES = {
    0: "Low",
    1: "Moderate",
    2: "High",
    3: "Critical"
}


def find_feature_file():
    for filename in CANDIDATE_FILES:
        path = os.path.join(DATA_DIR, filename)
        if os.path.exists(path):
            return path
    return None


def print_numeric_statistics(X, y, feature_names):
    print("\n========== FEATURE STATISTICS ==========")

    rows = []

    for i in range(X.shape[1]):
        values = X[:, i]

        means = []
        for class_id in range(4):
            class_values = values[y == class_id]
            means.append(
                float(np.mean(class_values))
                if len(class_values) else np.nan
            )

        rows.append({
            "feature_index": i,
            "feature_name": feature_names[i],
            "min": float(np.min(values)),
            "max": float(np.max(values)),
            "mean": float(np.mean(values)),
            "std": float(np.std(values)),
            "unique_values": int(len(np.unique(values))),
            "low_mean": means[0],
            "moderate_mean": means[1],
            "high_mean": means[2],
            "critical_mean": means[3]
        })

    df = pd.DataFrame(rows)

    print(
        df.to_string(
            index=False,
            max_rows=115
        )
    )

    return df


def main():

    print("\n" + "=" * 60)
    print("ARES 2.0 - FEATURE INSPECTION")
    print("=" * 60)

    if not os.path.exists(X_TRAIN_PATH):
        raise FileNotFoundError(
            f"Missing: {X_TRAIN_PATH}"
        )

    if not os.path.exists(Y_TRAIN_PATH):
        raise FileNotFoundError(
            f"Missing: {Y_TRAIN_PATH}"
        )

    X = np.load(X_TRAIN_PATH)
    y = np.load(Y_TRAIN_PATH)

    print("\n========== DATA ==========")
    print(f"X_train shape : {X.shape}")
    print(f"y_train shape : {y.shape}")

    # --------------------------------------------------------
    # Try to recover original feature names
    # --------------------------------------------------------

    feature_file = find_feature_file()

    print("\n========== FEATURE SOURCE ==========")

    if feature_file:
        print(f"Found feature file: {feature_file}")

        try:
            source_df = pd.read_csv(feature_file)

            print(f"Source shape : {source_df.shape}")
            print(
                "Source columns:",
                list(source_df.columns)
            )

            # If the CSV contains exactly the processed number
            # of feature columns, use its columns.
            if source_df.shape[1] == X.shape[1]:
                feature_names = list(source_df.columns)

            # Otherwise try to identify feature columns by
            # excluding common target/ID columns.
            else:
                excluded = {
                    "target",
                    "severity",
                    "label",
                    "class",
                    "id"
                }

                candidate_names = [
                    c for c in source_df.columns
                    if c.lower() not in excluded
                ]

                if len(candidate_names) == X.shape[1]:
                    feature_names = candidate_names
                else:
                    feature_names = [
                        f"feature_{i}"
                        for i in range(X.shape[1])
                    ]

        except Exception as e:
            print(
                f"Could not safely parse feature CSV: {e}"
            )
            feature_names = [
                f"feature_{i}"
                for i in range(X.shape[1])
            ]

    else:
        print(
            "No feature-name CSV found."
        )
        print(
            "Using generic feature indices."
        )

        feature_names = [
            f"feature_{i}"
            for i in range(X.shape[1])
        ]

    # --------------------------------------------------------
    # Validate feature count
    # --------------------------------------------------------

    if len(feature_names) != X.shape[1]:
        print(
            "\nWARNING: Feature-name count does not match "
            "X_train feature count."
        )

        feature_names = [
            f"feature_{i}"
            for i in range(X.shape[1])
        ]

    # --------------------------------------------------------
    # Print feature mapping
    # --------------------------------------------------------

    print("\n========== FEATURE MAPPING ==========")

    for i, name in enumerate(feature_names):
        print(f"{i:3d} -> {name}")

    # --------------------------------------------------------
    # Detailed statistics
    # --------------------------------------------------------

    stats_df = print_numeric_statistics(
        X,
        y,
        feature_names
    )

    # --------------------------------------------------------
    # Save inspection report
    # --------------------------------------------------------

    output_path = os.path.join(
        DATA_DIR,
        "feature_inspection_report.csv"
    )

    stats_df.to_csv(
        output_path,
        index=False
    )

    print("\n========== REPORT SAVED ==========")
    print(output_path)

    print("\n========== IMPORTANT ==========")
    print(
        "Use this report to identify what features 0-6, "
        "108, 107, 65, and 70 actually represent."
    )
    print(
        "Do NOT remove or manually modify features yet."
    )


if __name__ == "__main__":
    main()